// EDIT ME for each run.
// filter: '&filter_untranslated=1' | '&filter_tags=develop' | '&filter_keys=a::b,c::d' | '' (then set added_on)
// added_on: 'YYYY-MM-DD' to keep only keys created that day ('' = no date filter)
// repos: repo names in QR-CODE-App; branch_regex: extra branches to scan besides develop/main
// terms: [] = derive from key names automatically
return [{ json: {
  project_id: '479073796a6095e8c10e35.09051894',
  filter: '&filter_untranslated=1',
  pages: [1],
  added_on: '',
  repos: ['pdfhelp-monorepo'],
  branch_regex: '',
  terms: []
} }];

const c = $('Config').first().json;
const out = []; let total = null;
const STOP = { title:1, subtitle:1, name:1, card:1, description:1, label:1, text:1, button:1, types:1, forms:1, form:1, hero:1, metadata:1, components:1, navigation:1, dashboard:1, ogtitle:1, ogdescription:1, steps:1, faq:1, question:1, answer:1, placeholder:1, error:1, errors:1, common:1, homepage:1, instruction:1 };
const terms = {};
for (const it of $input.all()) {
  const r = it.json; const h = r.headers || {}; if (h['x-pagination-total-count']) { total = h['x-pagination-total-count']; }
  for (const k of ((r.body && r.body.keys) || [])) {
    if (k.is_archived) { continue; }
    if (c.added_on && String(k.created_at || '').indexOf(c.added_on) !== 0) { continue; }
    const name = (k.key_name && k.key_name.web) || k.key_name;
    let en = null; const untr = [];
    for (const t of (k.translations || [])) { const iso = (t.language_iso || '').toLowerCase(); if (iso === 'en') { en = t.translation; continue; } if (!t.translation || !String(t.translation).trim()) { untr.push(iso); } }
    out.push({ id: k.key_id, name: name, en: en, description: k.description, tags: k.tags, created_at: k.created_at, untranslated: untr.length, screenshots: (k.screenshots || []).length });
    for (const seg of String(name).split('::')) { const s = seg.toLowerCase(); if (s.length >= 4 && !STOP[s]) { terms[seg] = 1; } }
  }
}
let since = null;
for (const k of out) { const d = String(k.created_at || '').slice(0, 10); if (d && (!since || d < since)) { since = d; } }
if (since) { const dt = new Date(since + 'T00:00:00Z'); dt.setUTCDate(dt.getUTCDate() - 2); since = dt.toISOString().slice(0, 10); }
const batches = {};
for (const k of out) { const m = String(k.created_at || '').slice(0, 16); batches[m] = (batches[m] || 0) + 1; }
return [{ json: { total_header: total, count: out.length, batches: batches, since: since, terms: (c.terms && c.terms.length) ? c.terms : Object.keys(terms).slice(0, 80), keys: out } }];

const c = $('Config').first().json; const since = $('Keys').first().json.since || '2026-01-01';
const reqs = $('Repos').all(); const res = $input.all(); const out = [];
const extra = c.branch_regex ? new RegExp(c.branch_regex, 'i') : null;
for (let i = 0; i < res.length; i++) {
  const repo = reqs[i].json.repo;
  const names = (Array.isArray(res[i].json.body) ? res[i].json.body : []).map(function (b) { return b.name; });
  const pick = names.filter(function (n) { return /^(develop|dev|main|master)$/i.test(n) || (extra && extra.test(n)); });
  if (pick.length === 0) { pick.push('HEAD'); }
  for (const n of pick) { out.push({ json: { repo: repo, branch: n, since: since } }); }
}
return out;

const reqs = $('Commit Reqs').all(); const res = $input.all(); const seen = {}; const out = [];
for (let i = 0; i < res.length; i++) {
  const rq = reqs[i].json; const cs = Array.isArray(res[i].json.body) ? res[i].json.body : [];
  for (const c of cs) {
    const k = rq.repo + '@' + c.sha;
    if (seen[k]) { seen[k].branches.push(rq.branch); continue; }
    const o = { repo: rq.repo, sha: c.sha, branches: [rq.branch], message: (c.commit && c.commit.message || '').slice(0, 300), date: c.commit && c.commit.author && c.commit.author.date, author: c.commit && c.commit.author && c.commit.author.name, url: c.html_url };
    seen[k] = o; out.push({ json: o });
  }
}
if (out.length === 0) { out.push({ json: { repo: 'none', sha: 'none', branches: [], message: 'NO COMMITS FOUND' } }); }
return out.slice(0, 150);

const K = $('Keys').first().json; const TERMS = K.terms;
const cs = $('Pick Commits').all(); const res = $input.all();
const commits = []; const termHits = {}; const skippedSync = [];
for (let i = 0; i < res.length; i++) {
  const c = cs[i] ? cs[i].json : {};
  // Lokalise download/sync commits contain the keys too but are a consequence, not the origin.
  if (/lokalise/i.test(String(c.message))) { skippedSync.push((c.sha || '').slice(0, 9)); continue; }
  const files = (res[i].json.body && Array.isArray(res[i].json.body.files)) ? res[i].json.body.files : [];
  const hits = []; const hitFiles = {};
  for (const f of files) {
    for (const ln of (f.patch || '').split('\n')) {
      if (ln.charAt(0) !== '+') { continue; }
      const low = ln.toLowerCase();
      for (const t of TERMS) { if (low.indexOf(t.toLowerCase()) >= 0) { hitFiles[f.filename] = 1; termHits[t] = termHits[t] || {}; termHits[t][(c.sha || '').slice(0, 9)] = 1; if (hits.length < 40) { hits.push({ file: f.filename, term: t, line: ln.slice(0, 200) }); } } }
    }
  }
  if (hits.length) {
    const tickets = (String(c.message).match(/[A-Z][A-Z0-9]+-\d+/g) || []).filter(function (v, j, a) { return a.indexOf(v) === j; });
    commits.push({ sha: (c.sha || '').slice(0, 9), repo: c.repo, branches: c.branches, date: c.date, author: c.author, message: c.message, tickets: tickets, url: c.url, files_with_hits: Object.keys(hitFiles), sample: hits });
  }
}
const ticketTags = {};
for (const k of K.keys) { for (const t of (k.tags || [])) { if (/^[A-Z][A-Z0-9]+-\d+$/.test(t)) { ticketTags[t] = (ticketTags[t] || 0) + 1; } } }
const unmatched_terms = TERMS.filter(function (t) { return !termHits[t]; });
const unmatched_keys = K.keys.filter(function (k) { const segs = String(k.name).split('::'); return !segs.some(function (s) { return termHits[s]; }); }).map(function (k) { return { name: k.name, en: k.en, created_at: k.created_at, tags: k.tags }; });
return [{ json: { key_count: K.count, batches: K.batches, since: K.since, ticket_tags_on_keys: ticketTags, terms: TERMS, commits: commits, lokalise_sync_commits_skipped: skippedSync, unmatched_terms: unmatched_terms, unmatched_keys: unmatched_keys, keys: K.keys } }];
